/*Trigger*/

DELIMITER |

-- Trigger to log activity after inserting into activities table
CREATE TRIGGER after_activity_insert
AFTER INSERT ON activities
FOR EACH ROW
BEGIN
    VALUES (NEW.id, CONCAT('New activity added with ID: ', NEW.id), NOW());
END;|
DELIMITER ;

DELIMITER |

-- Trigger to log deletion of activities
CREATE TRIGGER after_activity_delete
AFTER DELETE ON activities
FOR EACH ROW
BEGIN
    VALUES (OLD.id, CONCAT('Activity deleted with ID: ', OLD.id), NOW());
END;|

DELIMITER ;