INSERT INTO `single` (`id`, `title`, `comefrom`, `pubdate`, `keywords`, `description`, `content`) VALUES
(1, 'About Us', 'This Site', '2024.11.29', 'Pet adoption, loving rescue, animal welfare', 'The pet adoption platform is an online service website dedicated to animal protection and loving rescue', '<p style=\"font-size:14px;color:#333333;font-family:arial, 宋体, sans-serif;background-color:#FFFFFF;\">\r\n	<span style=\"color:#05073B;font-family:-apple-system, BlinkMacSystemFont, &quot;font-size:15px;background-color:#FDFDFE;\"><img src=\"/pet_adoption2/admin/kindeditor/attached/image/20241129/002112.jpg\" alt=\"\" /><br />\r\n</span>\r\n</p>\r\n<p style=\"font-size:14px;color:#333333;font-family:arial, 宋体, sans-serif;background-color:#FFFFFF;\">\r\n	<span style=\"color:#05073B;font-family:-apple-system, BlinkMacSystemFont, &quot;font-size:15px;background-color:#FDFDFE;\">The platform brings together information on many pets to be adopted, providing stray animals with the opportunity to find a new home, and also providing an adoption channel for caring people to jointly promote animal welfare and harmonious coexistence between humans and animals.</span>\r\n</p>\r\n<p style=\"font-size:14px;color:#333333;font-family:arial, 宋体, sans-serif;background-color:#FFFFFF;\">\r\n	<img src=\"/1050/admin/kindeditor/attached/image/20201224/20201224084635_13834.jpg\" alt=\"\" /> \r\n</p>');
